//! The text of a CODEOWNERS file from the areas of `[[review.areas]]` (ADR 0018 decision 4).

use anyhow::{bail, Result};
use botica_config::{AreaName, ReviewConfig, Tier};

use super::pattern::Pattern;
use super::Host;

const HEADER: &str = "# Written by `botica review export --format codeowners` from the [[review.areas]] of the\n\
                      # configuration. Change the areas and run the command again; do not edit this file.\n";

const FORCED_COMMENT: &str =
    "# Always `platform` (ADR 0018 decision 1), with the owners of every `platform` entry.\n";

/// The files that GitLab reads before `.gitlab/CODEOWNERS`, which decide who owns the rest as
/// much as `.gitlab/CODEOWNERS` does.
const SHADOWING_CODEOWNERS: [&str; 2] = ["/CODEOWNERS", "/docs/CODEOWNERS"];

/// The areas from the lowest floor to the highest, the order of the sections of GitLab.
const SECTION_ORDER: [AreaName; 4] = [
    AreaName::Periphery,
    AreaName::Core,
    AreaName::Platform,
    AreaName::Critical,
];

/// One line of the file: a pattern, the area it comes from and its owners.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Line {
    pattern: Pattern,
    area: AreaName,
    tier: Tier,
    owners: Vec<String>,
}

impl Line {
    /// CODEOWNERS takes the last line that matches, so the lines go from the broadest to the
    /// narrowest: by tier, then by area (`platform` after `core`, which share a floor, since
    /// `platform` names the people who answer for it), then by the names they spell out, then by
    /// text, with a file before the folder of the same name. The order of the configuration never
    /// decides.
    fn order_key(&self) -> (Tier, usize, usize, String, bool) {
        let rank = SECTION_ORDER.iter().position(|area| *area == self.area);
        (
            self.tier,
            rank.unwrap_or_default(),
            self.pattern.literal_depth(),
            self.pattern.stem(),
            self.pattern.is_folder(),
        )
    }

    fn render(&self) -> String {
        let mut words = vec![self.pattern.text()];
        words.extend(self.owners.iter().cloned());
        format!("{}\n", words.join(" "))
    }
}

pub(super) fn render(review: &ReviewConfig, host: Host) -> Result<String> {
    if review.areas.is_empty() {
        bail!("the configuration has no [[review.areas]]: there is no owner to export");
    }
    if host == Host::Github {
        refuse_nested_groups(review)?;
    }
    let entries = sorted(entry_lines(review, host)?);
    refuse_two_owners(&entries, host)?;
    let forced = sorted(forced_lines(review)?);
    Ok(match host {
        Host::Github => github(&entries, &forced),
        Host::Gitlab => gitlab(review, &entries, &forced),
    })
}

/// GitHub names a team `@org/team` and has no `@org/group/team`, which only GitLab reads.
fn refuse_nested_groups(review: &ReviewConfig) -> Result<()> {
    let owners = review.areas.iter().flat_map(|area| &area.owners);
    if let Some(owner) = owners
        .into_iter()
        .find(|owner| owner.starts_with('@') && owner.matches('/').count() > 1)
    {
        bail!(
            "`{owner}` is a group of GitLab, which GitHub does not read: export with --host gitlab"
        );
    }
    Ok(())
}

/// The lines of the entries. On GitHub a line with no owners takes the path from a broader line
/// before it; GitLab refuses a line with no owners, and each area has its own section there, so
/// an entry with none adds no line.
fn entry_lines(review: &ReviewConfig, host: Host) -> Result<Vec<Line>> {
    let mut lines = Vec::new();
    let written = |owners: &[String]| host == Host::Github || !owners.is_empty();
    for area in review.areas.iter().filter(|area| written(&area.owners)) {
        for glob in &area.paths {
            for pattern in Pattern::read(glob)? {
                lines.extend(pattern.lines(host).into_iter().map(|pattern| Line {
                    pattern,
                    area: area.name,
                    tier: area.effective_tier(),
                    owners: area.owners.clone(),
                }));
            }
        }
    }
    Ok(lines)
}

/// The paths that are always `platform`, with the owners of every `platform` entry. A forced
/// path that ends in `**` is a folder and the others name files, so none needs a second line.
fn forced_lines(review: &ReviewConfig) -> Result<Vec<Line>> {
    let owners = platform_owners(review);
    let globs = review
        .forced_platform_globs()
        .into_iter()
        .chain(SHADOWING_CODEOWNERS.map(str::to_owned));
    let mut lines = Vec::new();
    for glob in globs {
        lines.extend(Pattern::read(&glob)?.into_iter().map(|pattern| Line {
            pattern,
            area: AreaName::Platform,
            tier: AreaName::Platform.floor(),
            owners: owners.clone(),
        }));
    }
    Ok(lines)
}

/// The owners of the `platform` entries, each once, in the order of the configuration.
fn platform_owners(review: &ReviewConfig) -> Vec<String> {
    let mut owners: Vec<String> = Vec::new();
    for area in review.areas.iter().filter(|a| a.name == AreaName::Platform) {
        for owner in &area.owners {
            if !owners.contains(owner) {
                owners.push(owner.clone());
            }
        }
    }
    owners
}

fn sorted(mut lines: Vec<Line>) -> Vec<Line> {
    lines.sort_by_key(Line::order_key);
    lines.dedup();
    lines
}

/// Two entries of one tier whose globs give the same line, as `x/**` and `x/`, with other owners:
/// which one wins would depend on the order of the configuration. GitLab writes each area in its
/// own section, so there only two entries of one area clash.
fn refuse_two_owners(lines: &[Line], host: Host) -> Result<()> {
    for (index, first) in lines.iter().enumerate() {
        let clash = lines[index + 1..].iter().find(|second| {
            second.order_key() == first.order_key()
                && second.owners != first.owners
                && (host == Host::Github || second.area == first.area)
        });
        if let Some(second) = clash {
            bail!(
                "`{}` comes from a `{}` entry and a `{}` entry with other owners: keep it in one \
                 entry",
                first.pattern.text(),
                first.area.name(),
                second.area.name()
            );
        }
    }
    Ok(())
}

/// GitHub reads one list: the lines of the entries, then the forced paths, so that no entry
/// takes a forced path from the owners of `platform`.
fn github(entries: &[Line], forced: &[Line]) -> String {
    let mut text = format!("{HEADER}\n");
    let mut rendered: Vec<String> = entries.iter().map(Line::render).collect();
    rendered.dedup();
    text.extend(rendered);
    text.push('\n');
    text.push_str(FORCED_COMMENT);
    text.extend(forced.iter().map(Line::render));
    text
}

/// GitLab reads one section for each area, and each section asks for its own approvals; the
/// forced paths close the section of `platform`.
fn gitlab(review: &ReviewConfig, entries: &[Line], forced: &[Line]) -> String {
    let mut text = HEADER.to_owned();
    for area in SECTION_ORDER {
        let lines: Vec<&Line> = entries.iter().filter(|line| line.area == area).collect();
        let closing = if area == AreaName::Platform {
            forced
        } else {
            &[]
        };
        if lines.is_empty() && closing.is_empty() {
            continue;
        }
        text.push('\n');
        text.push_str(&section_header(review, area));
        text.extend(lines.iter().map(|line| line.render()));
        if !closing.is_empty() {
            text.push_str(FORCED_COMMENT);
            text.extend(closing.iter().map(Line::render));
        }
    }
    text
}

/// `[critical][2]` asks for the largest `approvals` of the entries of the area; an area that
/// asks for none is an optional section, `^[periphery]`.
fn section_header(review: &ReviewConfig, area: AreaName) -> String {
    let approvals = review
        .areas
        .iter()
        .filter(|entry| entry.name == area)
        .map(|entry| entry.effective_approvals())
        .max()
        .unwrap_or(1);
    let name = area.name();
    if approvals == 0 {
        format!("^[{name}]\n")
    } else {
        format!("[{name}][{approvals}]\n")
    }
}
